hackerone_graphql.post_data:
{"operationName":"CurrentUser","variables":{"organizationHandle":null,"product_area":"other","product_feature":"other"},"query":"query CurrentUser($organizationHandle: String) {
  organizations_admin: organizations(
    where: {organization_members: {i_am_an_admin: true}}
  ) {
    total_count
    __typename
  }
  features(first: 200) {
    edges {
      node {
        id
        key
        enabled
        disabled
        global
        opted_in
        __typename
      }
      __typename
    }
    __typename
  }
  me {
    id
    _id
    bio
    name
    email
    signal
    website
    username
    location
    cleared
    verified
    teams {
      exists
      __typename
    }
    user_type
    created_at
    h1_pentester
    totp_enabled
    webauthn_enabled
    hackerone_triager
    hackerone_employee
    product_user_type
    view_profile
    has_active_ban
    has_restricted_access
    product_analytics {
      id
      amplitude_id
      __typename
    }
    user_display_options {
      id
      __typename
      theme_preference
    }
    profile_picture_small: profile_picture(size: small)
    profile_picture_medium: profile_picture(size: medium)
    profile_picture_xtralarge: profile_picture(size: xtralarge)
    edit_unclaimed_profiles
    i_can_view_gateway_v2_settings
    i_can_see_hai
    i_can_use_hai
    i_can_toggle_my_features
    features {
      id
      key
      enabled
      __typename
    }
    pentester_profile {
      id
      approved
      h1_pentester_lead
      __typename
    }
    active_ban {
      id
      starts_at
      ends_at
      duration_in_days
      __typename
    }
    allow_pentester_application
    organizations(
      where: {organization_members: {is_me: true}}
      order_by: {name: {_direction: ASC}}
    ) {
      nodes {
        id
        name
        handle
        profile_picture(size: small)
        enabled: handle
        hai_enabled
        bounty_insights_requested
        __typename
      }
      __typename
    }
    ...OrganizationsProviderFields
    tutorials {
      edges {
        node {
          id
          type
          complete
          __typename
        }
        __typename
      }
      __typename
    }
    __typename
  }
}

fragment OrganizationsFields on Organization {
  _id
  id
  handle
  name
  hai_enabled
  profile_picture(size: small)
  gate_flexible_asset_types_opened
  i_am_organization_admin
  i_can_view_bounty_insights
  i_can_view_organization_assets
  i_can_manage_organization_members
  i_can_view_custom_benchmarks
  i_can_manage_return_on_mitigation_settings
  i_can_view_spend_tracker
  i_can_view_spend_categories
  i_can_view_agentic_credit_usage
  triage_active
  entry_vdp_only
  bounty_insights_requested
  sales_demo
  teams(first: 1000, secure_order_by: {name: {_direction: ASC}}) {
    nodes {
      id
      databaseId: _id
      handle
      name
      is_team_member
      profile_picture(size: small)
      state
      type
      started_accepting_at
      launched_at
      created_at
      pentest {
        id
        databaseId: _id
        state
        start_date
        __typename
      }
      __typename
    }
    __typename
  }
  consumption_subscriptions {
    _id
    id
    __typename
  }
  organization_inboxes {
    nodes {
      id
      _id
      name
      inbox_type
      __typename
    }
    __typename
  }
  __typename
}

fragment OrganizationsProviderFields on User {
  id
  organizationByHandle: organizations(
    first: 1
    where: {handle: {_eq: $organizationHandle}}
  ) {
    nodes {
      id
      ...OrganizationsFields
      __typename
    }
    __typename
  }
  firstNonSalesDemoOrganization: organizations(
    first: 1
    where: {sales_demo: {_eq: false}}
  ) {
    nodes {
      id
      ...OrganizationsFields
      __typename
    }
    __typename
  }
  firstOrganization: organizations(first: 1) {
    nodes {
      id
      ...OrganizationsFields
      __typename
    }
    __typename
  }
  __typename
}"}
